import{_ as p,a0 as r,w as o,s as d,I as i,x as e,a1 as t,A as a,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何在免费 WiFi 中保护隐私（一） | LCTT x X-CMD","titleTemplate":false,"description":"如何在免费 WiFi 中保护隐私（一） | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在免费 WiFi 中保护隐私（一） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在免费 WiFi 中保护隐私（一） | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210803 Set up a VPN server on your Linux PC","title":"如何在免费 WiFi 中保护隐私（一）","tag":"202108","desc":""},"relativePath":"202108/20210803 Set up a VPN server on your Linux PC.md","filePath":"[post].md"}'),u={name:"202108/20210803 Set up a VPN server on your Linux PC.md"};function f(g,s,h,m,P,b){const n=r("Link");return o(),d("div",null,[s[28]||(s[28]=i("h1",{id:"如何在免费-wifi-中保护隐私-一",tabindex:"-1"},[e("如何在免费 WiFi 中保护隐私（一） "),i("a",{class:"header-anchor",href:"#如何在免费-wifi-中保护隐私-一","aria-label":"Permalink to “如何在免费 WiFi 中保护隐私（一）”"},"​")],-1)),s[29]||(s[29]=i("blockquote",null,[i("p",null,"第一步是安装一个“虚拟专用网络”服务器。")],-1)),s[30]||(s[30]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202108/13/213142rclc5htyfahotfas.jpg",alt:""})],-1)),s[31]||(s[31]=i("p",null,"你是否连接到了不受信任的网络，例如酒店或咖啡馆的 WiFi，而又需要通过智能手机和笔记本电脑安全浏览互联网？通过使用虚拟专用网络，你可以匿名访问不受信任的网络，就像你在专用网络上一样安全。",-1)),s[32]||(s[32]=i("p",null,"“虚拟专用网络” 是保护私人数据的绝佳工具。通过使用 “虚拟专用网络”，你可以在保持匿名的同时连接到互联网上的专用网络。",-1)),i("p",null,[s[1]||(s[1]=e("可选的 “虚拟专用网络” 服务有很多，",-1)),t(n,{href:"https://openvpn.net/"},{default:a(()=>[...s[0]||(s[0]=[e("0penVPN",-1)])]),_:1}),s[2]||(s[2]=e(" 依然是很多人在使用不受信任的网络时保护私人数据的第一选择。",-1))]),s[33]||(s[33]=i("p",null,"0penVPN 在两点之间创建一个加密通道，防止第三方访问你的网络流量数据。通过设置你的 “虚拟专用网络” 服务，你可以成为你自己的 “虚拟专用网络” 服务商。许多流行的 “虚拟专用网络” 服务都使用 0penVPN，所以当你可以掌控自己的网络时，为什么还要将你的网络连接绑定到特定的提供商呢？",-1)),s[34]||(s[34]=i("h3",{id:"搭建-linux-服务器",tabindex:"-1"},[e("搭建 Linux 服务器 "),i("a",{class:"header-anchor",href:"#搭建-linux-服务器","aria-label":"Permalink to “搭建 Linux 服务器”"},"​")],-1)),s[35]||(s[35]=i("p",null,"首先，在备用 PC 上安装一份 Linux。本例使用 Fedora，但是不论你使用的是什么 Linux 发行版，步骤基本是相同的。",-1)),i("p",null,[s[6]||(s[6]=e("从 ",-1)),t(n,{href:"http://getfedora.org"},{default:a(()=>[...s[3]||(s[3]=[e("Fedora 项目",-1)])]),_:1}),s[7]||(s[7]=e(" 网站下载最新的 Fedora ISO 副本。制作一个 USB 启动盘，将其插入到你的 PC 并启动，然后安装操作系统。如果你从未制作过可引导的 USB 启动盘，可以了解一下 ",-1)),t(n,{href:"https://opensource.com/article/20/10/fedora-media-writer"},{default:a(()=>[...s[4]||(s[4]=[e("Fedora Media Writer",-1)])]),_:1}),s[8]||(s[8]=e("。如果你从未安装过 Linux，请阅读 ",-1)),t(n,{href:"https://opensource.com/article/21/2/linux-installation"},{default:a(()=>[...s[5]||(s[5]=[e("三步安装 Linux",-1)])]),_:1}),s[9]||(s[9]=e("。",-1))]),s[36]||(s[36]=l(`<h3 id="设置网络" tabindex="-1">设置网络 <a class="header-anchor" href="#设置网络" aria-label="Permalink to “设置网络”">​</a></h3><p>安装完成 Fedora 操作系统后，登录到控制台或者 SSH 会话。</p><p>更新到最新并重新启动：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf update -y &amp;&amp; reboot</span></span></code></pre></div><p>重新登录并关闭防火墙：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>systemctl disable firewalld.service</span></span>
<span class="line"><span>systemctl stop firewalld.service</span></span></code></pre></div>`,6)),i("p",null,[s[11]||(s[11]=e("你可能希望在此系统上为你的内部网络添加适当的防火墙规则。如果是这样，请在关闭所有防火墙规则后完成 0penVPN 的设置和调试，然后添加本地防火墙规则。想要了解更多，请参照 ",-1)),t(n,{href:"https://www.redhat.com/sysadmin/secure-linux-network-firewall-cmd"},{default:a(()=>[...s[10]||(s[10]=[e("在 Linux 上设置防火墙",-1)])]),_:1}),s[12]||(s[12]=e("。",-1))]),s[37]||(s[37]=l(`<h3 id="设置-ip-地址" tabindex="-1">设置 IP 地址 <a class="header-anchor" href="#设置-ip-地址" aria-label="Permalink to “设置 IP 地址”">​</a></h3><p>你需要在你的本地网络设置一个静态 IP 地址。下面的命令假设在一个名为 <code>ens3</code> 的设备上有一个名为 <code>ens3</code> 的<ruby>网络管理器<rt>Network Manager</rt></ruby>连接。你的设备和连接名称可能不同，你可以通过打开 SSH 会话或从控制台输入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection show</span></span>
<span class="line"><span>NAME  UUID                                  TYPE      DEVICE</span></span>
<span class="line"><span>ens3  39ad55bd-adde-384a-bb09-7f8e83380875  ethernet  ens3</span></span></code></pre></div><p>你需要确保远程用户能够找到你的 “虚拟专用网络” 服务器。有两种方法可以做到这一点。你可以手动设置它的 IP 地址，或者将大部分工作交给你的路由器去完成。</p><h4 id="手动配置一个-ip-地址" tabindex="-1">手动配置一个 IP 地址 <a class="header-anchor" href="#手动配置一个-ip-地址" aria-label="Permalink to “手动配置一个 IP 地址”">​</a></h4><p>通过以下命令来设置静态 IP 地址、前缀、网关和 DNS 解析器，用来替换掉原有的 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo nmcli connection modify ens3 ipv4.addresses 10.10.10.97/24</span></span>
<span class="line"><span>$ sudo nmcli connection modify ens3 ipv4.gateway 10.10.10.1</span></span>
<span class="line"><span>$ sudo nmcli connection modify ens3 ipv4.dns 10.10.10.10</span></span>
<span class="line"><span>$ sudo nmcli connection modify ens3 ipv4.method manual</span></span>
<span class="line"><span>$ sudo nmcli connection modify ens3 connection.autoconnect yes</span></span></code></pre></div><p>设置主机名：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo hostnamectl set-hostname OVPNserver2020</span></span></code></pre></div><p>如果你运行了一个本地的 DNS 服务，你需要设置一个 DNS 条目，将主机名指向 “虚拟专用网络” 服务器的 IP 地址。</p><p>重启并确保系统的网络运行正常。</p><h4 id="在路由器中配置-ip-地址" tabindex="-1">在路由器中配置 IP 地址 <a class="header-anchor" href="#在路由器中配置-ip-地址" aria-label="Permalink to “在路由器中配置 IP 地址”">​</a></h4><p>在你的网络当中应该有一台路由器。你可能已经购买了它，或者从互联网服务提供商（ISP）那里获得了一台。无论哪种方式，你的路由器可能都有一个内置的 DHCP 服务，可以为连接到网络上的每台设备分配一个 IP 地址。你的新 “虚拟专用网络” 服务器也是属于网络的一台设备，因此你可能已经注意到它会自动分配一个 IP 地址。</p><p>这里的潜在问题是你的路由器不能保证每台设备都能在重新连接后获取到相同的 IP 地址。路由器确实尝试保持 IP 地址一致，但这会根据当时连接的设备数量而发生变化。</p><p>但是，几乎所有的路由器都会有一个界面，允许你为特定设备调停和保留 IP 地址。</p><p><img src="https://opensource.com/sites/default/files/uploads/reserved-ip.jpg" alt="Router IP address settings" title="Router IP address settings"></p><p>路由器没有统一的界面，因此请在你的路由器接口中搜索 “DHCP” 或 “Static IP address” 选项。为你的服务器分配自己的预留 IP 地址，使其在网络中保持 IP 不变。</p><h3 id="连接到服务器" tabindex="-1">连接到服务器 <a class="header-anchor" href="#连接到服务器" aria-label="Permalink to “连接到服务器”">​</a></h3><p>默认情况下，你的路由器可能内置了防火墙。这通常很好，因为你不希望网络之外的人能够强行进入你的任何计算机。但是，你必须允许发往 “虚拟专用网络” 服务器的流量通过防火墙，否则你的 “虚拟专用网络” 将无法访问，这种情况下你的 “虚拟专用网络” 服务器将形同虚设。</p><p>你至少需要一个来自互联网服务提供商的公共静态 IP 地址。使用其静态 IP 地址设置路由器的公共端，然后将你的 0penVPN 服务器放在专用端，在你的网络中使用专用静态 IP 地址。 0penVPN 默认使用 UDP 1194 端口。配置你的路由器，将你的公网 “虚拟专用网络” IP 地址的 UDP 1194 端口转发到 0penVPN 服务器上的 UDP 1194 端口。如果你决定使用不同的 UDP 端口，请相应地调整端口号。</p><h3 id="准备好-我们开始下一步" tabindex="-1">准备好，我们开始下一步 <a class="header-anchor" href="#准备好-我们开始下一步" aria-label="Permalink to “准备好，我们开始下一步”">​</a></h3><p>在本文中，你在服务器上安装并配置了一个操作系统，这已经成功了一半。在下一篇文章中，你将解决安装和配置 0penVPN 本身的问题。同时，请熟悉你的路由器并确保你可以从外部访问你的服务器。但是请务必在测试后关闭端口转发，直到你的 “虚拟专用网络” 服务启动并运行。</p><p>本文的部分内容改编自 D. Greg Scott 的博客，并经许可重新发布。</p><hr>`,24)),i("p",null,[s[14]||(s[14]=e("via: ",-1)),t(n,{href:"https://opensource.com/article/21/8/openvpn-server-linux"},{default:a(()=>[...s[13]||(s[13]=[e("https://opensource.com/article/21/8/openvpn-server-linux",-1)])]),_:1})]),i("p",null,[s[19]||(s[19]=e("作者：",-1)),t(n,{href:"https://opensource.com/users/greg-scott"},{default:a(()=>[...s[15]||(s[15]=[e("D. Greg Scott",-1)])]),_:1}),s[20]||(s[20]=e(" 选题：",-1)),t(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[16]||(s[16]=[e("lujun9972",-1)])]),_:1}),s[21]||(s[21]=e(" 译者：",-1)),t(n,{href:"https://github.com/perfiffer"},{default:a(()=>[...s[17]||(s[17]=[e("perfiffer",-1)])]),_:1}),s[22]||(s[22]=e(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[18]||(s[18]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[25]||(s[25]=e("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[23]||(s[23]=[e("LCTT",-1)])]),_:1}),s[26]||(s[26]=e(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...s[24]||(s[24]=[e("Linux中国",-1)])]),_:1}),s[27]||(s[27]=e(" 荣誉推出",-1))])])}const y=p(u,[["render",f]]);export{C as __pageData,y as default};
